all_original_proposals.original_declaration:
functional directed relationship BioticAbioticCoupling
    "An identified biological agent interacts with an identified abiotic material body."
    links imod:Agent to physical:MaterialBody;

abstract configuration BioticAbioticArrangement
    "A configuration recognized from biotic-abiotic coupling at an explicit ecological scope."
    emerges from ecology:BioticAbioticCoupling;

quantity PopulationAbundance
    "Number of individuals belonging to an identified population at the stated observation support."
    is imod:Numerosity of ecology:Population;

quantity SpeciesRichness
    "Number of distinct species identities represented in a community under stated inclusion criteria."
    is imod:Numerosity of ecology:Community;
